<div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Ticket report</h1><p class="text-secondary mb-0">Results are limited to tickets you are allowed to see.</p></div><a class="btn btn-outline-primary" href="<?= site_url('reports/export.csv') . (service('request')->getServer('QUERY_STRING') ? '?' . esc(service('request')->getServer('QUERY_STRING')) : '') ?>">Export CSV</a></div><form class="card card-body mb-3" method="get"><div class="row g-2"><div class="col-md-3"><label class="visually-hidden" for="q">Search</label><input class="form-control" id="q" name="q" placeholder="Ticket or subject" value="<?= esc(service('request')->getGet('q') ?? '') ?>"></div><div class="col-md-2"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach (['Open','In Progress','Resolved','Closed'] as $v): ?><option <?= service('request')->getGet('status') === $v ? 'selected' : '' ?>><?= esc($v) ?></option><?php endforeach ?></select></div><div class="col-md-2"><select class="form-select" name="priority"><option value="">All priorities</option><?php foreach (['Low','Medium','High'] as $v): ?><option <?= service('request')->getGet('priority') === $v ? 'selected' : '' ?>><?= esc($v) ?></option><?php endforeach ?></select></div><div class="col-md-2"><select class="form-select" name="category"><option value="">All categories</option><?php foreach ($categories as $c): ?><option value="<?= (int) $c['id'] ?>" <?= (string) service('request')->getGet('category') === (string) $c['id'] ? 'selected' : '' ?>><?= esc($c['name']) ?></option><?php endforeach ?></select></div><div class="col-md-1"><input class="form-control" type="date" name="from" aria-label="From" value="<?= esc(service('request')->getGet('from') ?? '') ?>"></div><div class="col-md-1"><input class="form-control" type="date" name="to" aria-label="To" value="<?= esc(service('request')->getGet('to') ?? '') ?>"></div><div class="col-md-1"><button class="btn btn-outline-primary w-100">Apply</button></div></div></form><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Ticket</th><th>Subject</th><th>Category</th><th>Priority</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach ($tickets as $ticket): ?><tr><td><a href="<?= site_url('tickets/' . $ticket['id']) ?>"><?= esc($ticket['ticket_number']) ?></a></td><td><?= esc($ticket['subject']) ?></td><td><?= esc($ticket['category_name']) ?></td><td><?= esc($ticket['priority']) ?></td><td><?= esc($ticket['status']) ?></td><td><?= esc($ticket['created_at']) ?></td></tr><?php endforeach ?><?php if (! $tickets): ?><tr><td colspan="6" class="text-center text-secondary py-4">No matching tickets.</td></tr><?php endif ?></tbody></table></div></div>
